"""Tests for the bulk discount module."""

from decimal import Decimal

import pytest

from pricing import LineItem
from pricing.bulk_discount import (
    BULK_DISCOUNT_PERCENT,
    BULK_QUANTITY_THRESHOLD,
    calculate_bulk_discount,
    qualifies_for_bulk_discount,
)


class TestQualifiesForBulkDiscount:
    """Tests for qualifies_for_bulk_discount()."""

    @pytest.mark.l4("C-8764baca")
    def test_quantity_exactly_threshold_qualifies(self):
        """ WHEN a line item has a quantity of exactly 10 THEN it qualifies."""
        item = LineItem("sku", Decimal("10.00"), 10)
        assert qualifies_for_bulk_discount(item) is True

    @pytest.mark.l4("C-e4015f6b")
    def test_quantity_greater_than_threshold_qualifies(self):
        """ WHEN a line item has a quantity greater than 10 THEN it qualifies."""
        item = LineItem("sku", Decimal("10.00"), 11)
        assert qualifies_for_bulk_discount(item) is True

    @pytest.mark.l4("C-4284227d")
    def test_quantity_below_threshold_does_not_qualify(self):
        """ WHEN a line item has a quantity of 9 or fewer THEN it does not qualify."""
        item = LineItem("sku", Decimal("10.00"), 9)
        assert qualifies_for_bulk_discount(item) is False

    @pytest.mark.l4("C-4284227d")
    def test_quantity_one_does_not_qualify(self):
        """Quantity of 1 should not qualify for bulk discount."""
        item = LineItem("sku", Decimal("10.00"), 1)
        assert qualifies_for_bulk_discount(item) is False


class TestCalculateBulkDiscount:
    """Tests for calculate_bulk_discount()."""

    @pytest.mark.l4("C-8764baca")
    def test_discount_on_quantity_exactly_threshold(self):
        """ WHEN quantity is exactly 10 THEN discount is 5% of total."""
        item = LineItem("sku", Decimal("10.00"), 10)  # total = 100.00
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("5.00")  # 5% of 100.00

    @pytest.mark.l4("C-e4015f6b")
    def test_discount_on_quantity_greater_than_threshold(self):
        """ WHEN quantity > 10 THEN discount is 5% of total."""
        item = LineItem("sku", Decimal("10.00"), 20)  # total = 200.00
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("10.00")  # 5% of 200.00

    @pytest.mark.l4("C-4284227d")
    def test_no_discount_on_quantity_below_threshold(self):
        """ WHEN quantity is 9 or fewer THEN discount is 0.00."""
        item = LineItem("sku", Decimal("10.00"), 9)
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.00")

    @pytest.mark.l4("C-1caf4da3")
    def test_half_up_rounding(self):
        """Discount amounts requiring half-up rounding are rounded correctly."""
        # 5% of 2.50 = 0.125 -> should round to 0.13
        item = LineItem("sku", Decimal("2.50"), 10)  # total = 25.00
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.13")  # half-up rounding of 0.125

    @pytest.mark.l4("C-1caf4da3")
    def test_half_up_rounding_with_exactly_half(self):
        """When discount is exactly halfway, round up (half-up)."""
        # 5% of 1.00 = 0.05 (no rounding needed)
        item = LineItem("sku", Decimal("1.00"), 10)  # total = 10.00
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.50")

    @pytest.mark.l4("C-1caf4da3")
    def test_half_up_rounding_with_amount_125(self):
        """5% of 2.50 = 0.125 rounds to 0.13 with half-up."""
        item = LineItem("sku", Decimal("2.50"), 10)
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.13")

    @pytest.mark.l4("C-1caf4da3")
    def test_half_up_rounding_with_amount_135(self):
        """5% of 2.70 = 0.135 rounds to 0.14 with half-up."""
        item = LineItem("sku", Decimal("2.70"), 10)
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.14")

    @pytest.mark.l4("C-4284227d", "C-1caf4da3")
    def test_zero_discount_for_non_qualifying_with_rounding_scenario(self):
        """Non-qualifying items return zero even with potential rounding amounts."""
        # 5% of 2.50 would be 0.125, but quantity is 9 so no discount
        item = LineItem("sku", Decimal("2.50"), 9)
        discount = calculate_bulk_discount(item)
        assert discount == Decimal("0.00")
